package vn.contractgovernance.api.privacy;
import java.util.*;
import java.util.concurrent.*;
import jakarta.annotation.PreDestroy;
import java.sql.Timestamp;
import org.springframework.stereotype.Service;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;
import vn.contractgovernance.api.shared.*;
import vn.contractgovernance.api.files.*;
import vn.contractgovernance.api.identity.UserDirectory;
import static vn.contractgovernance.api.obligation.DutyEvidence.id;
/** Durable reserved intent -> logical visibility -> real guarded cleanup -> fenced completion. */
@Service public class PrivacyJobs {
 private final PrivacyService privacy;private final PrivacyRecords records;private final EntityStore store;private final JobQueue queue;private final FileDispositions files;private final UserDirectory users;private final AuditService audit;private final ContractRegistry schemas;private final TransactionTemplate tx;private final UUID worker=UUID.randomUUID();private final Semaphore slots=new Semaphore(1);private final ExecutorService executor=Executors.newSingleThreadExecutor(Thread.ofPlatform().daemon(true).name("privacy-disposition-",0).factory());private final ScheduledExecutorService heartbeats=Executors.newSingleThreadScheduledExecutor(Thread.ofPlatform().daemon(true).name("privacy-lease-",0).factory());
 public PrivacyJobs(PrivacyService privacy,JobQueue queue,FileDispositions files,UserDirectory users,AuditService audit,ContractRegistry schemas,PlatformTransactionManager manager){this.privacy=privacy;this.records=privacy.records;this.store=records.store;this.queue=queue;this.files=files;this.users=users;this.audit=audit;this.schemas=schemas;this.tx=new TransactionTemplate(manager);}
 @Scheduled(fixedDelayString="${cg.disposition-poll-ms:1000}") public void poll(){if(!slots.tryAcquire())return;try{var job=queue.claimForKind("DATA_DISPOSITION",worker);if(job.isEmpty()){slots.release();return;}executor.execute(()->{try{process(job.get());}finally{slots.release();}});}catch(RuntimeException failure){slots.release();throw failure;}}
 private void lease(JobQueue.Job job){if(store.jdbc().queryForObject("select count(*) from cg_job where id=? and state='RUNNING' and lease_owner=? and attempts=? and lease_until>?",Long.class,job.id(),job.leaseOwner(),job.attempts(),java.sql.Timestamp.from(records.clock.instant()))!=1L)throw ApiException.of("STATE_CONFLICT","Disposition worker lease lost.");}
 private Actor actor(JobQueue.Job job){return users.actor(id(job.payload(),"officerId"));}
 public void process(JobQueue.Job job){var heartbeat=heartbeats.scheduleAtFixedRate(()->{try{queue.renew(job);}catch(RuntimeException unavailable){/* Final phase remains fenced; recovery owns expired lease. */}},20,20,TimeUnit.SECONDS);try{
  tx.executeWithoutResult(s->{var request=privacy.lock(job.targetId(),actor(job));privacy.authorize(job.targetId(),"EXECUTE",actor(job));lease(job);privacy.executionGuard(request,job.expectedHash(),job.expectedVersion(),actor(job),true);var decision=privacy.decision(request);if(!request.body().path("jobId").asString().equals(job.id().toString())||!job.payload().path("manifestHash").asString().equals(job.expectedHash()))throw ApiException.of("STORAGE_INTEGRITY","Disposition job/source binding mismatch.");store.jdbc().queryForObject("select set_config('cg.disposition_request',?,true)",String.class,request.id().toString());for(var record:request.body().path("manifest").path("records")){UUID recordId=id(record,"recordId");var row=reservation(request.id(),recordId);if(!records.json.hash(row.proof()).equals(row.hash()))throw ApiException.of("STORAGE_INTEGRITY","Reserved proof changed.");var frozen=java.util.stream.StreamSupport.stream(decision.path("proof").spliterator(),false).filter(p->p.path("recordId").equals(record.path("recordId"))).findFirst().orElseThrow();if(!row.proof().equals(frozen))throw ApiException.of("STORAGE_INTEGRITY","Reservation differs from approved decision.");if(row.phase().equals("RESERVED")){records.holds(recordId);var current=records.proof(request,record,actor(job),false);if(!privacy.sameProof(current,frozen))throw ApiException.of("BASE_CONFLICT","Current reserved record source changed.");if(record.path("action").asString().equals("CORRECT_CURRENT_METADATA")){store.jdbc().update("update cg_disposition_record set phase='DONE',result_version=? where request_id=? and record_id=? and phase='RESERVED'",record.path("expectedRecordVersion").asInt(),request.id(),recordId);}else files.logical(request.id(),store.require("File",recordId),record,frozen,id(request.body(),"decisionBy"));}}if(!queue.renew(job))throw ApiException.of("STATE_CONFLICT","Disposition lease lost before logical commit.");});
  // Physical IO is after logical intent committed, never hidden in an afterCommit success callback.
  var deletionIds=store.jdbc().query("select record_id from cg_disposition_record where request_id=? and action='DELETE_BYTES' and phase='LOGICAL' order by record_id",(rs,n)->rs.getObject(1,UUID.class),job.targetId());for(var recordId:deletionIds){tx.executeWithoutResult(s->{privacy.lock(job.targetId(),actor(job));privacy.authorize(job.targetId(),"EXECUTE",actor(job));records.currentGrants(store.require("DataRequest",job.targetId()),actor(job));lease(job);});files.cleanup(job.targetId(),recordId);tx.executeWithoutResult(s->{privacy.lock(job.targetId(),actor(job));privacy.authorize(job.targetId(),"EXECUTE",actor(job));lease(job);store.jdbc().update("update cg_disposition_record set phase='DONE' where request_id=? and record_id=? and phase='LOGICAL'",job.targetId(),recordId);if(!queue.renew(job))throw ApiException.of("STATE_CONFLICT","Disposition lease lost before cleanup acknowledgement.");});}
  tx.executeWithoutResult(s->{var request=privacy.lock(job.targetId(),actor(job));privacy.authorize(job.targetId(),"EXECUTE",actor(job));lease(job);privacy.executionGuard(request,job.expectedHash(),job.expectedVersion(),actor(job),true);if(store.jdbc().queryForObject("select count(*) from cg_disposition_record where request_id=? and phase<>'DONE'",Long.class,request.id())!=0L)throw ApiException.of("SERVICE_UNAVAILABLE","Disposition record cleanup incomplete.");var result=records.json.object().put("manifestHash",job.expectedHash()).put("manifestVersion",job.expectedVersion());privacy.event(request,"EXECUTION_COMPLETED",result,actor(job));var b=(ObjectNode)request.body().deepCopy();b.put("state","EXECUTED").put("updatedAt",records.now());var updated=store.update(request,b);schemas.validateSchema("DataRequest",updated.body());audit.record(actor(job),"EXECUTE",updated,"Exact approved disposition completed; byte cleanup confirmed");if(!queue.succeed(job))throw ApiException.of("STATE_CONFLICT","Disposition lease lost before completion.");});
 }catch(Exception failure){tx.executeWithoutResult(s->{queue.fail(job,failure instanceof ApiException a?a.code():"STORAGE_INTEGRITY","Disposition incomplete; exact committed intent retained for recovery");});}finally{heartbeat.cancel(false);}}
 @PreDestroy public void close(){executor.shutdownNow();heartbeats.shutdownNow();}
 private record Reservation(String phase,JsonNode proof,String hash){}
 private Reservation reservation(UUID request,UUID record){return store.jdbc().query("select phase,proof::text,proof_hash from cg_disposition_record where request_id=? and record_id=? for update",(rs,n)->new Reservation(rs.getString(1),records.json.parse(rs.getString(2)),rs.getString(3)),request,record).stream().findFirst().orElseThrow(()->ApiException.of("STORAGE_INTEGRITY","Missing disposition reservation."));}
 public void authorize(UUID request,Actor a){privacy.authorize(request,"EXECUTE",a);}
 public void requireRetry(EntityStore.Entity job,Actor a){var request=privacy.require(id(job.body(),"parentId"),a);authorize(request.id(),a);if(!job.body().path("state").asString().equals("FAILED")||!request.body().path("jobId").asString().equals(job.id().toString()))throw ApiException.of("STATE_CONFLICT","Not current failed disposition intent.");var hash=store.jdbc().queryForObject("select expected_hash from cg_job where id=?",String.class,job.id());privacy.executionGuard(request,hash,request.body().path("manifest").path("version").asInt(),a,true);for(var record:request.body().path("manifest").path("records")){var row=store.jdbc().query("select phase,proof::text,proof_hash from cg_disposition_record where request_id=? and record_id=?",(rs,n)->new Reservation(rs.getString(1),records.json.parse(rs.getString(2)),rs.getString(3)),request.id(),id(record,"recordId"));if(row.size()!=1)throw ApiException.of("STORAGE_INTEGRITY","Missing reserved intent.");if(row.getFirst().phase().equals("RESERVED")){records.holds(id(record,"recordId"));if(!privacy.sameProof(records.proof(request,record,a,false),row.getFirst().proof()))throw ApiException.of("BASE_CONFLICT","Reserved source changed; never execute a new manifest.");}}}
 public EntityStore.Entity retry(UUID id,String tag,String reason,Actor a){var preview=store.require("Job",id);privacy.lock(id(preview.body(),"parentId"),a);var job=store.lock("Job",id);ETags.check(tag,job.version());requireRetry(job,a);store.jdbc().update("update cg_job set payload=jsonb_set(payload,'{officerId}',to_jsonb(?::text)) where id=?",a.id().toString(),id);if(!queue.retry(id))throw ApiException.of("STATE_CONFLICT","Disposition job changed.");privacy.event(store.require("DataRequest",id(preview.body(),"parentId")),"RETRY",records.json.object().put("reason",reason),a);var updated=store.require("Job",id);audit.record(a,"RETRY",updated,reason);return updated;}
}
